package com.eventhub.dto; import com.eventhub.entity.*; import java.time.Instant; public record NoticeResponse(Long id,String title,String content,NoticePriority priority,boolean active,Long createdBy,String createdByName,Instant createdAt,Instant updatedAt){public static NoticeResponse from(Notice n){return new NoticeResponse(n.getId(),n.getTitle(),n.getContent(),n.getPriority(),n.isActive(),n.getCreatedBy().getId(),n.getCreatedBy().getFirstName()+" "+n.getCreatedBy().getLastName(),n.getCreatedAt(),n.getUpdatedAt());}}
